const api=window.__abyssal
if(!api)throw new Error('Abyssal C64 layer could not find core runtime')
const game=api.getGame?.();if(!game?.scene||!game?.ctx)throw new Error('Abyssal C64 layer could not find canvas runtime')
const scene=game.scene,screen=game.ctx,W=320,H=200,SX=800/W,SY=500/H
const low=document.createElement('canvas');low.width=W;low.height=H;const c=low.getContext('2d',{alpha:false});c.imageSmoothingEnabled=false;screen.imageSmoothingEnabled=false
const C={black:'#000000',white:'#ffffff',red:'#883932',cyan:'#67b6bd',purple:'#8b3f96',green:'#55a049',blue:'#40318d',yellow:'#bfce72',orange:'#8b5429',brown:'#574200',lred:'#b86962',dgrey:'#505050',grey:'#787878',lgreen:'#94e089',lblue:'#7869c4',lgrey:'#9f9f9f'}
const ACT={1:[C.black,C.brown,C.orange,C.yellow],2:[C.black,C.blue,C.cyan,C.lblue],3:[C.black,C.purple,C.lblue,C.white],4:[C.black,C.red,C.lred,C.orange]}
const DIRS=[{x:0,y:-1},{x:1,y:0},{x:0,y:1},{x:-1,y:0}],MAX=6
const frames=[{l:0,r:319,t:0,b:199},{l:24,r:295,t:19,b:181},{l:54,r:265,t:42,b:158},{l:82,r:237,t:61,b:139},{l:106,r:213,t:77,b:123},{l:125,r:194,t:89,b:111},{l:139,r:180,t:98,b:103}]
const px=(x,y,w,h,col)=>{c.fillStyle=col;c.fillRect(x|0,y|0,Math.max(1,w|0),Math.max(1,h|0))}
const ln=(x1,y1,x2,y2,col,w=1)=>{c.strokeStyle=col;c.lineWidth=w;c.beginPath();c.moveTo(x1|0,y1|0);c.lineTo(x2|0,y2|0);c.stroke()}
function dither(poly,colA,colB,step=4){c.save();c.beginPath();c.moveTo(poly[0][0],poly[0][1]);for(let i=1;i<poly.length;i++)c.lineTo(poly[i][0],poly[i][1]);c.closePath();c.clip();const xs=poly.map(p=>p[0]),ys=poly.map(p=>p[1]);const x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys);px(x0,y0,x1-x0+1,y1-y0+1,colA);c.fillStyle=colB;for(let y=y0;y<=y1;y+=step)for(let x=x0+((y/step)&1)*2;x<=x1;x+=step)c.fillRect(x|0,y|0,1,1);c.restore()}
function cell(side,forward){return scene.relativeCell?.(side,forward)??'#'}
function drawSegment(n,f,d,pal){const left=[[n.l,n.t],[f.l,f.t],[f.l,f.b],[n.l,n.b]],right=[[n.r,n.t],[f.r,f.t],[f.r,f.b],[n.r,n.b]],ceil=[[n.l,n.t],[n.r,n.t],[f.r,f.t],[f.l,f.t]],floor=[[n.l,n.b],[n.r,n.b],[f.r,f.b],[f.l,f.b]];dither(left,pal[1],d%2?C.dgrey:C.grey,5);dither(right,pal[1],C.black,6);dither(ceil,pal[0],C.dgrey,7);dither(floor,C.black,pal[1],5);ln(n.l,n.t,f.l,f.t,pal[2]);ln(n.r,n.t,f.r,f.t,pal[2]);ln(n.l,n.b,f.l,f.b,pal[2]);ln(n.r,n.b,f.r,f.b,pal[2]);ln(f.l,f.t,f.r,f.t,pal[3]);ln(f.l,f.b,f.r,f.b,pal[2]);if(cell(-1,d)!=='#')door(-1,n,f,pal);if(cell(1,d)!=='#')door(1,n,f,pal)}
function door(side,n,f,pal){const x=side<0?n.l:n.r,fx=side<0?f.l:f.r;const top=Math.round(n.t+(n.b-n.t)*.27),bot=Math.round(n.b-(n.b-n.t)*.08);c.fillStyle=C.black;c.beginPath();c.moveTo(x,top);c.lineTo(fx,f.t+3);c.lineTo(fx,f.b-2);c.lineTo(x,bot);c.closePath();c.fill();ln(x,top,fx,f.t+3,pal[3]);ln(x,bot,fx,f.b-2,pal[2])}
function frontWall(f,d,pal){const poly=[[f.l,f.t],[f.r,f.t],[f.r,f.b],[f.l,f.b]];dither(poly,pal[1],pal[0],4);for(let y=f.t+4;y<f.b;y+=7)ln(f.l,y,f.r,y,pal[2]);for(let x=f.l+7;x<f.r;x+=12)ln(x,f.t,x,f.b,pal[0]);const cx=(f.l+f.r)>>1,cy=(f.t+f.b)>>1;px(cx-2,cy-2,5,5,pal[3]);px(cx,cy,1,1,C.white)}
function atDepth(depth){const d=DIRS[scene.player.dir],x=scene.player.x+d.x*depth,y=scene.player.y+d.y*depth;return{x,y}}
function enemySprite(kind,boss,depth,pal){const f=frames[Math.min(depth,MAX)],cx=(f.l+f.r)>>1,ground=f.b-2,s=Math.max(1,Math.round((f.r-f.l)/42));const h=(boss?36:24)*s,w=(boss?22:14)*s,y=ground-h;const dark=C.black,body=boss?pal[3]:pal[2],hi=boss?C.white:pal[3];px(cx-w/2,y+h*.28,w,h*.72,dark);px(cx-w*.36,y+h*.08,w*.72,h*.3,body);px(cx-w*.28,y,w*.56,h*.18,dark);px(cx-w*.18,y+h*.1,w*.12,Math.max(1,s),hi);px(cx+w*.06,y+h*.1,w*.12,Math.max(1,s),hi);if(kind.includes('moth')){px(cx-w,y+h*.3,w*.45,h*.45,body);px(cx+w*.55,y+h*.3,w*.45,h*.45,body)}if(kind.includes('leech')){px(cx-w*.55,y+h*.72,w*1.1,h*.18,body)}if(kind==='choir'){for(let i=-2;i<=2;i++)px(cx+i*4*s,y+h*.12+(Math.abs(i)%2)*3*s,3*s,4*s,hi)}if(boss){ln(cx-w*.7,y+h*.36,cx-w*.95,ground,pal[3],Math.max(1,s));ln(cx+w*.7,y+h*.36,cx+w*.95,ground,pal[3],Math.max(1,s))}}
function drawEntity(depth,pal){const p=atDepth(depth);const e=scene.enemies?.find(x=>!x.defeated&&x.x===p.x&&x.y===p.y);if(e)enemySprite(e.kind,e.boss,depth,pal);const loot=scene.loot?.find(x=>!x.taken&&x.x===p.x&&x.y===p.y);if(loot){const f=frames[Math.min(depth,MAX)],cx=(f.l+f.r)>>1;px(cx-2,f.b-6,5,3,pal[3]);px(cx-1,f.b-7,3,1,C.white)}if(scene.layout?.exit?.x===p.x&&scene.layout?.exit?.y===p.y){const f=frames[Math.min(depth,MAX)],cx=(f.l+f.r)>>1,w=Math.max(4,(f.r-f.l)>>3),h=Math.max(8,(f.b-f.t)>>2);px(cx-w/2,f.b-h,w,h,C.black);ln(cx-w/2,f.b-h,cx+w/2,f.b-h,pal[3]);ln(cx-w/2,f.b-h,cx-w/2,f.b,pal[3]);ln(cx+w/2,f.b-h,cx+w/2,f.b,pal[3])}}
function activeEnemy(pal){const e=scene.activeEnemy?.();if(e)enemySprite(e.kind,e.boss,1,pal)}
function hud(pal){px(0,0,W,9,C.black);const name=String(scene.floorName||'ABYSS').toUpperCase().slice(0,24);c.fillStyle=pal[3];c.font='8px monospace';c.textBaseline='top';c.fillText(`ACT ${scene.floor||1}  ${name}`,4,1);c.fillStyle=C.lgrey;c.fillText(`HP ${Math.max(0,scene.hp|0)}/${scene.maxHp|0}  SAN ${Math.max(0,scene.sanity|0)}/${scene.effectiveMaxSanity?.()??scene.baseMaxSanity??0}`,168,1);px(0,191,W,9,C.black);c.fillStyle=pal[3];c.fillText('A/D TURN  W/S MOVE  E USE  F ATTACK',4,192)}
function render(){if(scene.mode==='title'||!scene.layout){scene.__c64Legacy?.();return}const pal=ACT[scene.floor]||ACT[1];px(0,0,W,H,C.black);px(0,9,W,182,pal[0]);let wall=MAX+1;for(let d=1;d<=MAX;d++){if(cell(0,d)==='#'){wall=d;break}}for(let d=Math.min(MAX,wall);d>=1;d--)drawSegment(frames[d-1],frames[d],d,pal);if(wall<=MAX)frontWall(frames[wall],wall,pal);for(let d=Math.min(MAX,wall-1);d>=1;d--)drawEntity(d,pal);activeEnemy(pal);hud(pal);screen.save();screen.imageSmoothingEnabled=false;screen.clearRect(0,0,800,500);screen.drawImage(low,0,0,800,500);screen.restore();scene.drawMinimap?.();scene.drawCompass?.();scene.drawCrosshair?.();scene.drawLocalSpecialMarker?.();scene.drawSetpieceAura?.();if(scene.hp<=0)scene.drawOverlay?.('LOST TO THE ABYSS','Load your save or begin another expedition');else if(scene.mode==='ending')scene.drawOverlay?.(scene.endingTitle,'The expedition is complete');else scene.clearOverlay?.();scene.emit?.()}
scene.__c64Legacy=scene.draw.bind(scene);scene.draw=render;game.canvas.style.imageRendering='pixelated';game.canvas.style.background=C.black;document.body.classList.add('c64-mode');if(scene.mode!=='title'&&scene.layout)scene.draw()
function stamp(){const b=document.getElementById('badge');if(b)b.textContent='C64 EDITION · v2.3.0';const k=document.querySelector('.v14-kicker');if(k)k.textContent=api.getLanguage?.()==='es'?'EDICIÓN C64 · v2.3.0':'C64 EDITION · v2.3.0'}
game.events.on('snapshot',stamp);setTimeout(stamp,0)
window.__abyssalV23={version:'2.3.0',renderer:'c64-pixel',redraw:render,internalResolution:[320,200]}
